// Static world data generated by client/scripts/game-text.ts (quest offers, travel routes, item
// names). The server re-checks every rule; this only decides what the UI offers.
import type { Character } from '@pockie/shared'
import data from './world-data.json'
import { plainText } from './text'
import type { Quest } from './types'

interface Offer {
  npc: string
  scene: number
  pre: number
  level: number
  nation: number
  talkKey: string | null
}

export interface Destination {
  sceneId: number
  level: number
  nation: number
}

const offers = data.offers as Record<string, Offer>
const travel = data.travel as Record<string, Destination[]>
const itemNames = data.itemNames as Record<string, string>
const previous = data.previous as Record<string, number>
const stepArgs = data.stepArgs as Record<string, string[][]>

/** EXP needed to go from `level` to the next one; undefined at the level cap. */
export const expToNext = (level: number) =>
  level >= data.maxLevel ? undefined : (data.levelExp as Record<string, number>)[level + 1]

export const sceneNameKey = (sceneId: number) => `lg_Scene_BackGround_${sceneId}`
const equipment = new Set(data.equipment)
export const isEquipment = (itemId: string) => equipment.has(itemId)
const usable = new Set(data.usable)
export const isUsable = (itemId: string) => usable.has(itemId)
export const itemNameKey = (itemId: string) => itemNames[itemId] ?? `lg_${itemId}`

const allowed = (character: Character, level: number, nation: number) =>
  character.level >= level && (nation === -1 || nation === character.nation)

/**
 * Quests the character can pick up now, from any NPC. Completed quests are not listed by the API,
 * so a quest counts as done when a later quest of its chain is held; of an unheld chain only the
 * first quest shows.
 * ponytail: a heuristic; an "available quests" endpoint would make it exact.
 */
export function availableQuests(character: Character, held: Quest[]) {
  const heldIds = new Set(held.map((q) => q.taskId))
  const done = new Set<number>()
  for (const quest of held) {
    for (let pre = previous[quest.taskId] ?? 0; pre > 0 && !done.has(pre);) {
      done.add(pre)
      pre = previous[pre] ?? 0
    }
  }
  const candidates = Object.entries(offers)
    .map(([id, offer]) => ({ taskId: Number(id), ...offer }))
    .filter(
      (offer) =>
        !heldIds.has(offer.taskId) &&
        !done.has(offer.taskId) &&
        !heldIds.has(offer.pre) &&
        allowed(character, offer.level, offer.nation),
    )
  const ids = new Set(candidates.map((offer) => offer.taskId))
  return candidates.filter((offer) => !ids.has(offer.pre))
}

/** Quests this NPC can hand out now. */
export function questOffers(npcId: string, sceneId: number, character: Character, held: Quest[]) {
  return availableQuests(character, held).filter(
    (offer) => offer.npc === npcId && offer.scene === sceneId,
  )
}

/** Home village of each nation (Character.nation). */
const VILLAGES = [111, 121, 151, 141, 131]
export const villageOf = (nation: number) => VILLAGES[nation] ?? VILLAGES[0]!
export const isVillage = (sceneId: number) => VILLAGES.includes(sceneId)

/**
 * Where a held quest leads: the zone and NPC (or monster) of its first unfinished step, or of
 * its last step once every step is done.
 */
export function questTarget(quest: Quest): { sceneId?: number; npcId?: string } {
  const open = quest.steps.findIndex((step, i) => (quest.progress[i] ?? 0) < step.target)
  const args = stepArgs[quest.taskId]?.[open === -1 ? quest.steps.length - 1 : open] ?? []
  const scene = /^lg_Scene_BackGround_(\d+)$/.exec(args[0] ?? '')
  const npc = /^lg_name_(n\d+)$/.exec(args[1] ?? '')
  return { sceneId: scene ? Number(scene[1]) : undefined, npcId: npc?.[1] }
}

/** Scenes reachable from here that this character may enter, plus locked ones for the map. */
export function destinations(character: Character) {
  return (travel[character.sceneId] ?? [])
    .filter((d) => d.nation === -1 || d.nation === character.nation)
    .map((d) => ({ ...d, open: allowed(character, d.level, d.nation) }))
}

/** Arguments for a quest step's generic template: zone, NPC/monster, item names and counts. */
export function questStepArgs(taskId: number, step: number, current: number, total: number) {
  return (stepArgs[taskId]?.[step] ?? []).map((arg) =>
    arg === '#total' ? total : arg === '#current' ? current : arg && plainText(arg),
  )
}
